using System;
using System.Linq;
using System.Collections.ObjectModel;

// Focused reference snippets and separate complete crafting examples. Canonical aliases/signatures come from the language registry.
public static class BlueprintGuide
{
    static Entry MaterialFunction(BlueprintAlias alias)
    {
        string title,details;
        switch(alias.Id){
        case BlueprintFeature.StarlightCount:title="별빛 개수";details="StarIron: 별철 작업물. 현재 별빛 개수를 반환하며 원본은 바꾸지 않습니다.";break;
        case BlueprintFeature.StarlightRead:title="별빛 값 읽기";details="StarIron: 별철 작업물. Index: 0부터 시작하는 현재 위치. 해당 정수 값을 반환합니다.";break;
        case BlueprintFeature.StarlightSwap:title="별빛 교환";details="StarIron: 별철 작업물. A, B: 0부터 시작하는 두 위치. 원본을 교환하며 반환값은 없습니다. 같은 위치는 시간 비용이 없습니다.";break;
        case BlueprintFeature.StarlightRemove:title="별빛 제거";details="StarIron: 별철 작업물. Index: 제거할 위치. 반환값은 없으며, 뒤의 값이 앞으로 이동하므로 같은 위치를 다시 확인하세요.";break;
        case BlueprintFeature.CoolingCount:title="냉각 지점 수";details="Blade: 냉각할 칼날. 지점 번호는 0부터 시작합니다.";break;
        case BlueprintFeature.CoolingStart:title="냉각 입구";details="Blade: 냉각할 칼날. 경로의 시작 지점 번호를 반환합니다.";break;
        case BlueprintFeature.CoolingEnd:title="냉각 출구";details="Blade: 냉각할 칼날. 경로의 마지막 지점 번호를 반환합니다.";break;
        case BlueprintFeature.CoolingCost:title="통로 비용 조회";details="Blade: 칼날. A, B: 두 지점 번호. 연결이 없거나 같은 지점이면 -1입니다. 잘못된 지점 번호는 오류입니다. 조회에는 서리수를 쓰지 않습니다.";break;
        case BlueprintFeature.CoolingRun:title="경로 냉각";details="Blade: 칼날. FrostWater: 서리수 번호 8. Path: 입구부터 출구까지의 정수 지점 배열. 유효 경로의 통로 비용 합만큼 소비합니다. 경로가 끊겼거나 재료가 부족하면 변경 없이 오류가 납니다.";break;
        case BlueprintFeature.BoneLength:title="용뼈 전체 길이";details="Bone: 용뼈 작업물. 절단 전 최초 전체 길이를 정수로 반환합니다.";break;
        case BlueprintFeature.BoneCount:title="필수 마디 수";details="Bone: 용뼈 작업물. 최초 마디 수를 정수로 반환하며 절단 후에도 줄지 않습니다.";break;
        case BlueprintFeature.BonePosition:title="마디 위치 조회";details="Bone: 용뼈 작업물. Index: 0부터 시작하는 마디 번호. 최초 왼쪽 끝 기준의 고정 위치를 정수로 반환합니다.";break;
        case BlueprintFeature.BoneCut:title="용뼈 절단";details="Bone: 용뼈 작업물. Position: 92로 읽은 고정 위치. 해당 조각을 자르며 반환값은 없습니다. 현재 조각 길이만큼 시간 비용이 듭니다. 없는 마디나 이미 자른 위치는 오류입니다.";break;
        case BlueprintFeature.BoneIsCut:title="절단 여부 확인";details="Bone: 용뼈 작업물. Position: 필수 마디의 고정 위치. 절단 완료 여부를 불리언으로 반환합니다. 필수 마디가 아닌 위치는 오류입니다.";break;
        default:title="누적 절단 비용";details="Bone: 용뼈 작업물. 완료된 절단의 누적 비용을 정수로 반환합니다. 골드 지출액이 아닙니다.";break;
        }
        return new Entry("material-function-"+alias.Symbol,"금속 가공",alias.Symbol+"() · "+title,details,"","","",alias.Id);
    }
    public const string IntroductionTitle="대장간에 오신 것을 환영합니다!";
    public const string Introduction="이 안내서는 현재 성장 트리와 대장장이 트리의 기능을 설명합니다. 분야별 책갈피에서 함수와 예제를 찾아보세요.\n\n처음부터 쓸 수 있는 것은 재료 올리기 1, 가열 2, 타격 3, 냉각 4, 손잡이 제작 5와 ! 제출입니다. 철·나무·물은 공급 연구 없이 재료 상점에서 구매합니다. 기본 공정으로 제작하고 완성품을 판매해 첫 연구 자금을 모으세요.\n\n제어문 해금은 조건·반복·반복 제어·사용자 함수를 한 번에 엽니다. 이후 금속 가공, 행운, 마력 가공, 공방 운영, 시간 조회, 기술 연구로 분기합니다. 함수마다 필요한 선행 연구가 다르며, 연결된 조건은 모두 구매해야 합니다.\n\n스피드는 1~5단계를 순서대로 구매합니다. 5단계 이후 자동판매 노드를 별도로 구매해야 자동판매와 해당 안내서가 해금됩니다. 재료 공급 해금비와 실제 재료 구매비는 별개입니다.\n\n대장장이 트리는 다이아로 고용 인원을 늘리고 조회 기능을 연구합니다. ‘대장장이’ 책갈피에서 고용, 병렬 제작, 선물과 거대한 룬을 확인하세요.\n\n안내서의 예제를 복사하는 것만으로 연구나 재료가 지급되지는 않습니다. ▷ 한 줄 실행도 실제 재료를 소비합니다.";
    public sealed class Entry
    {
        public readonly string Id,Section,Title,Body,Example,Expected,Note;
        public readonly BlueprintFeature Feature;
        readonly string numericTitle,numericBody,numericExample,numericNote;
        public string ResearchFor(bool englishUnlocked)=>"";
        public bool ShowResearch => false;
        public bool IsFunctionReference => Alias!=null&&Alias.Syntax==BlueprintSyntaxKind.Builtin||Id=="1"||Id=="2"||Id=="3"||Id=="4"||Id=="finish";
        public BlueprintAlias Alias => BlueprintAliases.Find(Feature);
        public string Heading => FormatHeading(true);
        public string Description => DescriptionFor(true);
        string Describe(string body){
            if(Feature==BlueprintFeature.Match||Feature==BlueprintFeature.SmithRun||Feature==BlueprintFeature.Wrap||Feature==BlueprintFeature.Rune||Feature==BlueprintFeature.RuneList||Feature==BlueprintFeature.RuneFamily||Feature==BlueprintFeature.RuneGrade||Feature==BlueprintFeature.Slots)return body;
            var alias=Alias;if(alias==null)return body;
            string summary=alias.Description+"\n"+alias.Signature;
            return body==alias.Description||body==summary?summary:summary+"\n\n"+body;
        }
        public Entry(string id,string section,string title,string body,string example,string expected,string note,BlueprintFeature feature,string numericTitle=null,string numericBody=null,string numericExample=null,string numericNote=null)
        {this.numericTitle=numericTitle??title;this.numericBody=numericBody??body;this.numericExample=numericExample??example;this.numericNote=numericNote??note;Id=id;Section=BlueprintResearchGuide.SectionFor(feature,section);Title=title;Body=body;Example=example;Expected=BlueprintResearchGuide.FormatGold(expected);Note=note;Feature=feature;}
        public string HeadingFor(bool englishUnlocked) => FormatHeading(englishUnlocked);
        string FormatHeading(bool english)
        {
            string title=english?Title:numericTitle;
            var alias=Alias;
            if(alias==null)return title;
            string symbol=alias.Symbol.Length==0?alias.English:alias.Symbol;
            bool included=title.StartsWith(symbol,StringComparison.Ordinal)
                &&(title.Length==symbol.Length||!char.IsLetterOrDigit(title[symbol.Length])&&title[symbol.Length]!='_');
            if(included){
                if(!english||alias.Symbol.Length==0)return title;
                int end=symbol.Length;
                if(title.Substring(end).StartsWith("()",StringComparison.Ordinal))end+=2;
                string suffix=title.Substring(end).TrimStart(' ','·');
                return title.Substring(0,end)+" / "+alias.English+(suffix.Length==0?"":" · "+suffix);
            }
            return (english&&alias.Symbol.Length>0?symbol+" / "+alias.English:symbol)+" · "+title;
        }
        public string DescriptionFor(bool englishUnlocked) => BlueprintResearchGuide.FormatGold((Id=="notation"?"영어 제어 예약어는 테크 트리의 '영어 예약어' 연구(150,000G)로 해금합니다. 숫자·기호 표기는 계속 사용할 수 있습니다.\n\n":"")+Describe(englishUnlocked?Body:numericBody)+(Feature==BlueprintFeature.While?"\n\n888(1):은 계속 반복하고 888(0):은 실행하지 않습니다. 0이 아닌 정수는 참입니다. !!로 빠져나오거나 실행 중지 버튼으로 멈출 수 있으며, 실행 안전 한도에 도달하면 중단됩니다.":""));
        public string ExampleFor(bool englishUnlocked) => englishUnlocked?Example:numericExample;
        public string NoteFor(bool englishUnlocked) => BlueprintResearchGuide.FormatGold(englishUnlocked?Note:numericNote);
        public bool Matches(string query,bool englishUnlocked)
        {return string.IsNullOrWhiteSpace(query)||(Section+" "+HeadingFor(englishUnlocked)+" "+DescriptionFor(englishUnlocked)).IndexOf(query.Trim(),StringComparison.OrdinalIgnoreCase)>=0;}
        public bool Matches(string query)
        {return string.IsNullOrWhiteSpace(query)||(Section+" "+Heading+" "+Description).IndexOf(query.Trim(),StringComparison.OrdinalIgnoreCase)>=0;}
    }
    static Entry SealEntry(BlueprintFeature feature)
    {
        if(feature==BlueprintFeature.Wrap)return new Entry("extension-201","공방 운영","201() · 봉인층 쌓기",
            "식힌 검날에 봉인을 쌓고, 마지막 층부터 해제하면 판매 보너스를 얻습니다.\n\n준비: 성형하고 열을 0으로 식힌 철·별철 검날\n쌓기: 201(검날, 종류) · 최대 6층\n종류: 1 열(석탄 1개), 2 수(물 1개), 3 충격(나무 1개)\n해제: 202(검날, 종류) · 마지막에 쌓은 종류부터, 추가 재료 없음\n확인: 203(검날) · 남은 층 수\n\n보상: 정상 해제한 층마다 판매가 +140G · 검 하나당 최대 6회(+840G)\n주의: 다른 종류로 해제하면 해당 층의 보너스를 잃습니다. 봉인이 남은 채 제출하면 판매가는 0G입니다.",
            "p = 1(1)\n2(p)\n3(p)\n4(p, 0)\n201(p, 2) # 물 1개로 봉인\n202(p, 2) # 같은 종류로 해제\n!p",
            "물 봉인 1층을 해제해 판매가 +140G.","종류 번호는 재료 번호와 다릅니다. 여러 층은 쌓은 순서의 반대로 해제하세요.",feature);
        string symbol=BlueprintAliases.Find(feature).Symbol;
        string usage=feature==BlueprintFeature.Wrap?"201(검날, 종류)는 봉인층을 추가합니다. 반환값은 None입니다. 아래 예제는 3종류를 쌓고 역순으로 해제합니다.":feature==BlueprintFeature.Unwrap?"202(검날, 종류)는 맨 위 층과 같은 종류를 지정해 해제합니다. 반환값은 None입니다. 아래 예제는 1 → 2 → 3으로 쌓은 층을 3 → 2 → 1로 해제합니다.":"203(검날)은 아직 남아 있는 봉인층 수(0~6)를 정수로 반환합니다. 재료 소비는 없습니다. 아래 예제는 물 봉인 2층을 쌓고, 남은 개수가 0이 될 때까지 해제합니다.";
        string example="p = 1(1)\n2(p)\n3(p)\n4(p, 0)\n"+(feature==BlueprintFeature.SealCount?"201(p, 2)\n201(p, 2)\nprint(203(p)) # 2\n888(203(p) > 0):\n    202(p, 2)\nprint(203(p)) # 0\n!p":"201(p, 1) # 석탄 1개\n201(p, 2) # 물 1개\n201(p, 3) # 나무 1개\n202(p, 3) # 마지막 층부터 해제\n202(p, 2)\n202(p, 1)\n!p");
        return new Entry("extension-"+symbol,"공방 운영",symbol+"() · "+(feature==BlueprintFeature.Wrap?"봉인층 쌓기":feature==BlueprintFeature.Unwrap?"봉인층 해제":"남은 봉인층 조회"),usage+"\n\n"+"봉인은 식은 검날에 층을 쌓고, 마지막에 쌓은 층부터 정확히 해제해 판매 보너스를 얻는 공정입니다. 성형하고 열을 0으로 식힌 철 또는 별철 검날을 준비하세요.\n\n종류와 재료: 1 = 열 봉인(석탄 1개, 20G), 2 = 수 봉인(물 1개, 1G), 3 = 충격 봉인(나무 1개, 3G). 종류 번호는 재료 번호와 다릅니다. 봉인을 쌓을 때만 재료를 소비하고, 202() 해제에는 추가 재료가 들지 않습니다.\n\n이익: 손상되지 않은 층을 정확히 해제하면 결계 보너스가 층당 +140G, 검 하나당 최대 6회·+840G까지 쌓입니다. 봉인이 한 층이라도 남은 채 제출하면 미완성품으로 판정되어 판매가가 0G입니다. 203(검날)이 0인지 확인하고 모든 층을 해제한 뒤 제출하세요. 보너스는 제출 후 판매할 때 반영되며, 즉시 골드가 지급되는 것은 아닙니다.\n\n활용: 종류별 보상은 같습니다. 물 봉인 1층은 재료 1G로 판매가 +140G를 얻으므로 재료비를 뺀 추가 이익은 139G입니다. 물 봉인 6층을 모두 정확히 해제하면 추가 이익은 834G입니다. 연구비·추가 작업 시간은 별도이며, 균열 감점이나 다른 판매 배율이 없는 경우의 비교입니다.",example,
            feature==BlueprintFeature.SealCount?"철 1개·물 2개 소비. 결계 +280G, 기본 철 검날 28G와 합쳐 판매가 308G.":"철·석탄·물·나무 각 1개 소비. 결계 +420G, 기본 철 검날 28G와 합쳐 판매가 448G.",
            "한 번에 남겨둘 수 있는 봉인은 최대 6층입니다. 해제 후 다시 쌓을 수 있지만 결계 보너스는 검 하나당 총 6회까지만 누적됩니다.\n\n1 → 2 → 3 순으로 쌓았다면 3 → 2 → 1 순으로 해제하세요. 틀린 종류로 해제하면 맨 위 층이 손상되고 그대로 남습니다. 이후 올바른 종류로 제거해도 그 층의 보너스는 복구되지 않습니다. 아래의 다른 층은 정상 해제 시 보너스를 받을 수 있습니다. 빈 상태에서 202()를 호출하면 오류입니다.\n\n203()은 남은 개수만 알려주며 맨 위 종류나 누적 보너스는 알려주지 않습니다. 같은 종류만 쌓으면 개수를 확인하며 반복 해제하기 쉽고, 종류를 섞으면 쌓은 순서를 기록해 역순으로 처리하세요. 봉인 해제는 202()를 사용하며 일반 가열·냉각·망치질 함수로 대신하지 않습니다."+"\n\n"+(feature==BlueprintFeature.SealCount?"예제 판매가 308G - 재료비 7G = 301G.":"예제 판매가 448G - 재료비 29G = 419G.")+" 연구비와 다른 판매 효과는 제외한 값입니다.",feature);
    }
    static Entry MatchGuide()=>new Entry("match","조건과 반복","696 · 선택 분기","여러 선택지 중 값에 맞는 행동 하나를 고를 때 사용합니다. 값을 한 번 확인하고 위에서부터 비교해, 처음 맞는 분기만 실행합니다. break/!!는 필요하지 않습니다.\n\n696 값: → 선택 시작\n6? 값: → 이 값이면 실행\n6? 1 | 2: → 1 또는 2이면 실행\n9?: → 어느 분기도 맞지 않으면 실행(마지막에 작성)\n\nPython에서는 match 값:, case 값:, case _:로 씁니다. case는 match보다 4칸, 실행할 코드는 case보다 4칸 더 들여씁니다.\n\n확장 사용법: case n은 값을 n에 저장합니다(기존 n과 비교하지 않습니다). case n if n > 3:은 추가 조건을 확인합니다. 숫자 표기는 6? n 1? n > 3:입니다. 목록은 case [첫값, *나머지]:처럼 나누어 받을 수 있습니다.\n\nrandom 연구 다음에 선택 분기를 5K로 구매합니다. 영문 표기는 영어 예약어 연구도 필요합니다.","choice = 66(1, 3)\nmatch choice:\n    case 1:\n        print(\"철을 선택했습니다\")\n    case 2 | 3:\n        print(\"다른 재료를 선택했습니다\")\n    case _:\n        print(\"해당하는 선택이 없습니다\")","선택값에 맞는 문장 하나만 출력됩니다.","정수·문자열·True/False·None, |, _, 이름 받기, as, 조건, 목록·튜플·딕셔너리 패턴을 지원합니다. 클래스 패턴은 지원하지 않으며, 컬렉션은 기존 도면 언어처럼 정수만 담습니다. 비교할 변수 값은 case 이름이 아니라 조건식이나 모듈.이름으로 확인하세요.",BlueprintFeature.Match,numericExample:"choice = 66(1, 3)\n696 choice:\n    6? 1:\n        print(\"철을 선택했습니다\")\n    6? 2 | 3:\n        print(\"다른 재료를 선택했습니다\")\n    9?:\n        print(\"해당하는 선택이 없습니다\")");
    static Entry RuneReference(ForgeExpansion.Definition d)
    {
        string title,body,example,note="";
        int perGrade=ForgeBalance.RuneGradeBonus,fullSet=ForgeBalance.TripleRuneBonus;
        switch(d.Alias.Id){
            case BlueprintFeature.Rune:
                title="룬 각인";
                body="룬은 검에 새기는 마법 문양입니다. 룬을 새긴 검은 팔 때 골드를 더 받습니다.\n\n【처음에는 이렇게】\n룬 연구를 구매하고, 성형한 철·별철 검날을 완전히 식히세요. 211(검날, 룬 번호)로 문양을 새깁니다. 해당 번호의 재료 1개를 쓰며, 검 하나에 최대 3개까지 새길 수 있습니다.\n\n【얼마나 더 받나요?】\n1~3번: 1등급 · 하나당 +"+perGrade+"G\n4~6번: 2등급 · 하나당 +"+(perGrade*2)+"G\n7~9번: 3등급 · 하나당 +"+(perGrade*3)+"G\n서로 다른 계열 3개를 채우면 ‘삼중 공명’ +"+fullSet+"G를 추가로 받습니다.\n\n【어떤 룬을 고르나요?】\n계열은 함께 새길 수 있는 조합을 구분하는 종류입니다. 1·4·7번, 2·5·8번, 3·6·9번이 각각 같은 계열이며, 각 계열에서 하나씩만 선택할 수 있습니다.\n재료 대응:\n1 철\n2 나무\n3 물\n4 석탄\n5 은\n6 마력 수정\n7 별철\n8 서리수\n9 용뼈\n7·8·9번에는 별철·서리수·용뼈가 각각 1개 필요합니다. 세 룬의 보너스 +"+(perGrade*9+fullSet)+"G를 얻습니다.";
                example="p = 1(1)\n2(p)\n3(p)\n4(p, 0) # 검날 식히기\n211(p, 1) # 철 1개\n211(p, 2) # 나무 1개\n211(p, 3) # 물 1개\n5(p, 2) # 나무 손잡이\n!p";
                note="보너스는 완성품을 판매할 때 받습니다. 재료 구매비와 연구비는 별도이므로 보너스 전부가 순이익은 아닙니다. 균열 감점이나 판매 배율이 있으면 최종 금액이 달라집니다.";
                break;
            case BlueprintFeature.RuneList:
                title="룬 후보 목록 조회";
                body="검에 새길 수 있는 룬 번호 1~9를 확인합니다. 212()는 목록만 보여주며, 재료나 룬을 지급하지 않습니다.\n\n실제로 새길 때는 211(검날, 번호)를 사용합니다. 처음에는 기본 재료인 철·나무·물로 1·2·3번을 하나씩 새겨보세요. 조회에는 재료나 골드가 들지 않습니다.";
                example="print(212()) # 룬 번호 1~9";
                break;
            case BlueprintFeature.RuneFamily:
                title="룬 계열 조회";
                body="두 룬을 같은 검에 새겨도 되는지 확인할 때 사용합니다. 213(룬 번호)는 계열 번호를 알려줍니다. 같은 계열은 하나만 새길 수 있습니다.\n\n1계열: 1·4·7번\n2계열: 2·5·8번\n3계열: 3·6·9번\n\n예를 들어 7번과 8번은 함께 새길 수 있지만, 1번과 7번은 함께 새길 수 없습니다. 세 계열을 모두 채우면 삼중 공명 +"+fullSet+"G를 받습니다. 조회 비용은 없습니다.";
                example="print(213(7)) # 1계열\nprint(213(8)) # 2계열";
                break;
            case BlueprintFeature.RuneGrade:
                title="룬 등급 조회";
                body="룬을 새겼을 때 판매가가 얼마나 오르는지 확인하는 함수입니다. 214(룬 번호)는 등급을 알려줍니다.\n\n1~3번: 1등급 · +"+perGrade+"G\n4~6번: 2등급 · +"+(perGrade*2)+"G\n7~9번: 3등급 · +"+(perGrade*3)+"G\n\n각인에는 룬 번호와 동일한 재료 번호의 재료 1개가 필요합니다. 조회만으로 보너스가 붙지는 않으며, 실제 각인은 211()로 합니다. 조회 비용은 없습니다.";
                example="print(214(7)) # 3등급";
                break;
            default:
                title="남은 룬 슬롯 조회";
                body="검에 룬을 몇 개 더 새길 수 있는지 확인합니다. ‘슬롯’은 룬을 새길 자리이며, 검 하나에 3자리가 있습니다.\n\n215(검날)는 남은 자리 수를 알려줍니다. 처음에는 3, 하나를 새기면 2, 세 개를 모두 새기면 0입니다. 자리가 남아 있어도 같은 계열을 중복해서 새길 수는 없습니다. 조회 비용은 없습니다.";
                example="p = 1(1)\n2(p)\n3(p)\n4(p, 0)\n211(p, 7)\nprint(215(p)) # 2자리 남음";
                break;
        }
        return new Entry("extension-"+d.Alias.Symbol,"마력 가공",d.Alias.Symbol+"() · "+title,body,example,"",note,d.Alias.Id);
    }
    static Entry MagicReference(ForgeExpansion.Definition d)
    {
        string title,body,example,note;
        if(d.Alias.Id==BlueprintFeature.Charge){
            title="9() · 마력 충전";
            body="【사용법】\n손잡이를 단 식은 검에 9(검, 1)을 세 번 호출합니다. 첫 충전에서만 마력 수정 1개를 소비합니다.\n\n【이익】\n3회 충전이 완료되면 판매가에 마력 전도 보너스 +"+ForgeBalance.ChargeBonus+"G가 붙습니다. 수정 1개 가격 30G를 뺀 추가 이익은 "+(ForgeBalance.ChargeBonus-30)+"G입니다. 다른 판매 효과와 연구비는 제외한 값입니다.";
            example=d.Example+"\n!p";
            note="세기 2·3은 충전량을 늘리지 않고 균열을 만듭니다. 세기 1을 사용하세요. 이미 3회 충전한 검에는 다시 호출할 수 없습니다. 반환값은 None이며, 보너스는 검을 판매할 때 받습니다.";
        }else if(d.Alias.Id==BlueprintFeature.Inspect){
            title="102() · 작업물 상태 조회";
            body="102(작업물, 항목 번호)는 현재 상태를 정수로 알려주는 조회 함수입니다. 재료나 골드를 소비하지 않고 작업물을 바꾸지도 않습니다.\n\n0: 재료 번호\n1: 담금질 경도\n2: 손잡이 재료 번호 (없으면 0)\n3: 균열 여부 (있으면 1, 없으면 0)\n4: 연마 여부 (완료 1, 미완료 0)\n5: 충전 횟수 (0~3)\n6: 공명 활성 여부 (활성 1, 비활성 0)\n7: 냉각으로 확정된 마력 등급\n\n【활용】\n102(검, 3)으로 균열을 확인하거나, 102(검, 5)가 3인지 확인해 충전 완료 여부를 판단하세요. 온도는 100(작업물)로 조회합니다.";
            example="p = 1(1)\nprint(102(p, 0)) # 철의 재료 번호 1\nprint(102(p, 2)) # 손잡이 없음 0\nprint(102(p, 3)) # 균열 없음 0";
            note="첫 인자에는 재료 번호가 아니라 1()로 만든 작업물 변수를 넣으세요. 항목 번호는 0~7입니다. 102() 자체에는 판매 보너스가 없습니다.";
        }else{
            title="402() · 현재 단조 강도 조회";
            body="402(작업물)은 마력 단조의 현재 강도 0~9를 정수로 돌려줍니다. 소수 부분은 버리며 조회 비용과 재료 소비는 없습니다.\n\n【사용법】\n401(검날)로 마력 단조를 활성화하고 가열한 뒤 타격하세요. 타격으로 강도가 올라가며, 마지막 타격 후 1초가 지나면 초당 1씩 낮아집니다. 402(검날)로 현재 강도를 확인해 냉각할 시점을 정할 수 있습니다.\n\n【이익】\n402() 자체의 판매 보너스는 없습니다. 마력 단조 중 냉각하면 그때의 강도가 마력 등급으로 확정되고, 등급당 +"+ForgeBalance.MagicGradeBonus+"G가 판매가에 붙습니다. 확정된 등급은 102(검날, 7)로 확인합니다.";
            example="p = 1(1)\n401(p)\n2(p)\n3(p)\nprint(402(p)) # 현재 강도 확인\n4(p, 0)\nprint(102(p, 7)) # 냉각 시 확정된 등급\n!p";
            note="현재 강도는 시간이 지나면 달라집니다. 402()는 강도를 올리거나 유지하는 함수가 아닙니다. 예제의 401() 활성화에는 마력 수정 1개가 필요합니다.";
        }
        return new Entry("extension-"+d.Alias.Symbol,"마력 가공",title,body,example,d.Alias.Id==BlueprintFeature.Charge?"3회 충전 완료 · 마력 전도 판매 보너스 +"+ForgeBalance.ChargeBonus+"G":d.Alias.Id==BlueprintFeature.Inspect?"재료 1, 손잡이 0, 균열 0을 출력합니다.":"현재 단조 강도와 냉각으로 확정된 마력 등급을 출력합니다.",note,d.Alias.Id);
    }
    static Entry FuelEntry()=>new Entry(
        "extension-8","확장 제작","8() · 화로 온도 설정",
        "【무슨 함수인가요?】\n8(온도)는 석탄 1개로 화로를 설정합니다. 예: 8(1000). 검을 직접 가열하지 않으므로, 이어서 2(Blade)를 실행해야 검이 화로 온도까지 달궈집니다. 설정 범위는 100~1200°C입니다. 도면 실행을 시작할 때 화로는 900°C이며 같은 실행 안에서는 설정이 유지됩니다. 대장장이마다 화로는 독립적입니다.\n\n【적정 온도를 맞춰 보세요】\n철·별철 검날은 처음 달굴 때 850~1100°C 중 적정 온도가 무작위로 정해지고, 다시 가열해도 바뀌지 않습니다. 100(Blade, 1)로 적정 온도를 측정한 뒤 8(측정값), 2(Blade), 3(Blade), 4(Blade, 3) 순서로 작업하세요.\n\n【골드 보너스】\n850°C 이상에서 가열·망치질한 뒤 같은 온도에서 물로 식히면 담금질 +19G입니다. 검의 적정 온도에 정확히 맞췄다면 추가 +81G, 총 +100G를 받습니다. 다른 특성이나 균열이 없는 철 검날은 128G에 판매됩니다. 반복 담금질로 보너스가 중첩되지는 않습니다.",
        "Blade = 1(1)\n2(Blade) # 기본 화로 900°C로 첫 가열\nTarget = 100(Blade, 1) # 이 검의 적정 온도 측정\n8(Target) # 석탄 1개로 화로 조절\n2(Blade) # 조절한 온도로 다시 가열\n3(Blade) # 이 온도에서 망치질\n4(Blade, 3) # 물로 담금질\n!Blade",
        "기본 28G + 담금질 19G + 적정 온도 81G = 판매가 128G.",
        "예제에는 철·석탄·물 각 1개가 필요하며 재료 구매비는 별도입니다. 화로만 조절하거나 망치질을 생략하면 정밀 담금질 보너스를 받지 못합니다. 재가열하면 이전 담금질 효과가 초기화되므로 다시 망치질하고 물로 식히세요. 공기·서리수 냉각에는 담금질 골드 보너스가 없습니다. 8()의 반환값은 None입니다.",
        BlueprintFeature.Fuel);
    static Entry PolishEntry()=>new Entry(
        "extension-6","확장 제작","6() · 검날 연마",
        "【사용법】\n6(검날 변수)를 호출하세요. 예: 6(Blade). 재료 번호가 아니라 1()로 만든 작업물을 전달합니다. 반환값은 None이며, 전달한 검날 자체에 연마가 적용됩니다.\n\n【사용 순서】\n철 또는 별철 검날을 가열하고 타격해 성형한 다음, 4()로 열을 0까지 식힌 뒤 연마합니다. 뜨겁거나 성형되지 않은 작업물에는 사용할 수 없습니다.\n\n【장점】\n연마한 검에는 판매가 계산 시 "+ForgeBalance.PolishBonus+"골드의 연마 보너스가 붙습니다. 연마 자체는 골드나 추가 재료를 소비하지 않습니다.\n7() 은도금 전에 연마하면 도금 보너스를 받을 수 있습니다. 연마하지 않고 도금하면 은만 소비하고 도금 보너스는 받지 못합니다.\n10() 용뼈 정제에도 연마한 검날이 필요합니다. 이때 검날에 균열이 없어야 합니다.",
        "Blade = 1(1) # 철 검날 준비\n2(Blade) # 가열\n3(Blade) # 성형\n4(Blade, 0) # 공기로 냉각\n6(Blade) # 식은 검날 연마\n!Blade",
        "연마한 철 검날을 제출합니다. 연마 보너스 +"+ForgeBalance.PolishBonus+"골드.",
        "먼저 연마 연구를 해금하세요. 연구비와 재료 구매비는 별도입니다. 같은 검날을 여러 번 연마해도 보너스는 중첩되지 않으며, 연마로 균열을 없앨 수는 없습니다.",
        BlueprintFeature.Polish);
    public static readonly ReadOnlyCollection<Entry> Entries=Array.AsReadOnly(new[]{
        new Entry("start","시작하기","첫 검날 만들기","도면은 위에서 아래로 실행됩니다. 재료를 올리고, 가열하고, 타격한 다음 냉각하세요. !로 현재 결과물을 제출하고 평가받습니다. ! 없이도 공정과 계산을 실행할 수 있습니다.\n▷는 한 줄 실행입니다. 누를 때마다 다음 실행 줄을 처리하고 멈추며 변수와 작업물 상태를 유지합니다. ▶는 전체 실행 또는 멈춘 지점부터 계속 실행, ■는 중단입니다. 두 실행 모두 실제 재료를 소비합니다. 파란 줄이 다음 실행 위치입니다.","Material = 1\nBlade = 1(Material)\n2(Blade)\n3(Blade)\n4(Blade, 0)\n!Blade","철 1개 · 제작비 0G · 판매가 28G · 순이익 28G","예제를 복사해 코드 창에 붙여 넣으세요. 실제 제작에는 철 1개가 필요하며 골드는 소비하지 않습니다.",BlueprintFeature.None),
        new Entry("variables","시작하기","변수 · 대입 · 들여쓰기","이름 = 값으로 값을 저장합니다. 이름은 문자 또는 _로 시작하며 대소문자를 구분합니다. 한글 이름도 가능합니다.\n블록은 : 뒤에서 시작하며 공백 4칸씩 들여씁니다. Enter는 자동 들여쓰기, Tab/Shift+Tab은 들여쓰기 조절입니다.\nif와 반복문 안에서 대입한 값은 같은 실행 범위에 남습니다. 실제로 값을 읽기 전에는 대입해야 합니다.","if True:\n    인사 = \"안녕하세요\"\nprint(인사)","디버그 창에 안녕하세요 출력","실행하지 않은 분기에서만 값을 대입했다면 변수 읽기 줄에서 오류가 납니다. 함수의 지역 변수는 호출 밖으로 나오지 않습니다.",BlueprintFeature.None,numericBody:"이름 = 값으로 값을 저장합니다. 이름은 문자 또는 _로 시작하며 대소문자를 구분합니다. 한글 이름도 가능합니다.\n블록은 : 뒤에서 시작하며 공백 4칸씩 들여씁니다. Enter는 자동 들여쓰기, Tab/Shift+Tab은 들여쓰기 조절입니다.\n1?와 반복문 안에서 대입한 값은 같은 실행 범위에 남습니다. 실제로 값을 읽기 전에는 대입해야 합니다.",numericExample:"1?(True):\n    인사 = \"안녕하세요\"\nprint(인사)"),
        new Entry("notation","시작하기","영문과 숫자 표기","영문과 숫자·기호 표기는 같은 기능입니다. 한 도면에 섞어 써도 됩니다.\n100(Blade)는 열 조회 함수지만 Value = 100의 100은 숫자입니다. 000()은 min()의 정확한 숫자 표기입니다.\n# 뒤는 주석입니다. 따옴표 문자열 안의 기호는 실행되지 않습니다.\n함수 이름은 연노랑, 제어문은 보라, 재료는 분홍, 주석은 초록, 변수는 흰색입니다.","Value = 100\nDistance = 101(-3) # abs(-3)과 같음\nprint(\"01?와 !!도 문자열 안에서는 글자\")","Value는 100, Distance는 3. 따옴표 안의 문장 출력","",BlueprintFeature.None,numericTitle:"숫자와 기호 표기",numericBody:"숫자·기호는 쓰인 위치에 따라 명령이나 값을 뜻합니다.\n100(Blade)는 열 조회 함수지만 Value = 100의 100은 숫자입니다. 000()은 목록의 최솟값을 구합니다.\n# 뒤는 주석입니다. 따옴표 문자열 안의 기호는 실행되지 않습니다.\n함수 이름은 연노랑, 제어문은 보라, 재료는 분홍, 주석은 초록, 변수는 흰색입니다.",numericExample:"Value = 100\nDistance = 101(-3) # 절댓값은 3\nprint(\"01?와 !!도 문자열 안에서는 글자\")"),
        new Entry("1","대장간 공정","1() · 재료 올리기","사용법: 작업물 = 1(재료 번호)\n등록된 재료 번호 0~9를 받습니다. 0 공기, 1 철, 2 나무, 3 물, 4 석탄, 5 은, 6 마력 수정, 7 별철, 8 서리수, 9 용뼈입니다. 해당 재료 1개만 소비합니다. 공기는 재고를 소비하지 않습니다. 반환된 작업물은 재료 정보를 유지합니다. 1(1)만 호출하거나 다른 함수의 인자로 전달해도 실행됩니다.","Blade = 1(1)","철 검날 완성 · 제작비 0G","예: Wood = 1(2), Water = 1(3). 실제 실행에는 해금과 보유량이 필요합니다. 미등록 번호·잘못된 타입은 오류입니다. 현재 성형되어 식은 철 검날은 28G, 원재료와 나머지 미완성품은 0G입니다.",BlueprintFeature.None),
        new Entry("2","대장간 공정","2() · 가열","사용법: 2(작업물)\n작업물을 현재 화로 온도까지 가열합니다. 기본 화로는 900°C입니다. 8(온도)로 화로를 바꾼 뒤 2(작업물)을 실행하면 그 온도가 적용됩니다. 첫 가열 뒤 100(검날, 1)로 검별 적정 온도(850~1100°C)를 측정할 수 있습니다. 골드나 재료를 소비하지 않으며 None을 반환합니다.","2(Blade)","철 검날 완성 · 제작비 0G","두 번째 인자는 사용하지 않습니다. 기존 2(Blade, 7)은 2(Blade)로 고치세요. 다시 가열하면 이전 담금질 효과가 초기화됩니다.",BlueprintFeature.None),
        new Entry("3","대장간 공정","3() · 타격","사용법: 3(작업물)\n작업물을 두드립니다. 온도가 850°C 이상일 때 성형되며 비용은 0G입니다. None을 반환합니다.","3(Blade)","철 검날 완성 · 제작비 0G","850°C 미만에서도 타격 동작은 실행되지만 성형 효과는 없습니다. 성형하려면 먼저 2(Blade)을 실행하세요.",BlueprintFeature.None),
        new Entry("4","대장간 공정","4() · 냉각","사용법: 4(작업물, 냉각 재료)\n작업물과 냉각에 사용할 재료 번호를 전달합니다. 냉각 방법은 두 번째 인자로 지정합니다. 공기(0), 물(3), 서리수(8)를 사용할 수 있습니다. 열을 0으로 내리며 물은 뜨거운 성형 검날에 경도 7을 부여합니다. 공기를 사용할 때 비용은 0G이며 None을 반환합니다.","4(Blade, 0)","철 검날 완성 · 제작비 0G","물·서리수는 각각 재료 1개를 소비합니다. 물은 850°C 이상에서 가열한 뒤 망치질한 검날에 담금질 +19G, 적정 온도와 정확히 일치하면 추가 +81G를 부여합니다. 서리수는 100~900°C에서 서리 문양을 부여합니다.",BlueprintFeature.None),
        new Entry("extension-5","대장간 공정","5() · 손잡이 제작","사용법: 5(Item, Material)\n성형하고 식힌 검날에 선택한 재료 1개로 손잡이를 만듭니다. 철(1), 나무(2), 은(5), 별철(7)을 사용할 수 있습니다. 기본 제공 함수이며 골드는 소비하지 않습니다. None을 반환합니다.\n기존 정제 용뼈·공명 수정 작업물 장착도 지원합니다.","p = 1(1)\n2(p)\n3(p)\n4(p, 0)\n5(p, 2)\n!p","나무 손잡이가 있는 검 완성","손잡이 재료 1개가 필요합니다. 이미 손잡이가 있는 검에는 다시 만들 수 없습니다.\n5(Item, Material)의 두 번째 인자는 손잡이 재료입니다. 예: 5(p, 2)의 2는 나무이며, 코드 창과 안내서 예제에서 분홍색으로 표시됩니다. 색약 배려·고대비 설정에서는 선택한 재료 강조색을 사용합니다.",BlueprintFeature.Attach),
        new Entry("finish","대장간 공정","! · 완성품 판정","사용법: !작업물\n작업물 또는 등록된 재료 번호를 제출합니다. 반복문 안에서는 제출 후 다음 명령과 반복을 계속하고, 반복문 밖에서는 현재 도면 또는 사용자 함수를 끝냅니다. 사용자 함수 안에서 제출하면 함수는 None을 반환하고 호출한 곳의 다음 명령을 계속합니다. 식은 철 검날은 28G, 원재료·미완성품은 0G입니다. res = 1 다음 줄에 !res를 쓰면 철 1개를 그대로 제출합니다. 원재료 제출은 가공비 없이 해당 재고만 소비합니다. ! 없이도 실행할 수 있습니다.","!Blade","철 검날 완성 · 제작비 0G","!는 함수 호출이 아닙니다. 반복문 안에서 사용할 수 있으며 매번 새 작업물을 만들어 제출하세요. 이미 제출한 작업물은 다시 사용할 수 없습니다. 사용자 함수 안에서도 !res로 직접 제출할 수 있습니다. 함수의 반복문 안에서는 제출 후 반복을 계속합니다. 90904()로 맡긴 함수가 직접 제출한 검은 중복 자동 제출되지 않습니다.",BlueprintFeature.None),
        new Entry("if","조건과 반복","조건이 참일 때","사용법: 1?(조건): 또는 if 조건:\n조건이 True이면 들여쓴 블록을 실행합니다. 조건은 비교식 또는 True/False여야 합니다.","Heat = 7\n1?(Heat > 7):\n    print(\"너무 뜨겁습니다\")\n01?(Heat >= 6):\n    print(\"타격할 수 있습니다\")\n0?:\n    print(\"더 가열하세요\")","타격할 수 있습니다 출력","1?(1):처럼 정수를 조건으로 넣으면 오류입니다.",BlueprintFeature.If,numericBody:"사용법: 1?(조건):\n조건이 True이면 들여쓴 블록을 실행합니다. 조건은 비교식 또는 True/False여야 합니다."),
        new Entry("elif","조건과 반복","다음 조건 검사","사용법: 01?(조건): 또는 elif 조건:\n앞에서 선택된 분기가 없을 때 다음 조건을 검사합니다. 여러 개 연결할 수 있지만 첫 참 분기 하나만 실행합니다.","Heat = 7\n1?(Heat > 7):\n    print(\"너무 뜨겁습니다\")\n01?(Heat >= 6):\n    print(\"타격할 수 있습니다\")\n0?:\n    print(\"더 가열하세요\")","첫 번째 조건은 거짓, 두 번째 조건만 실행","if와 같은 들여쓰기에서 작성하세요. elif를 단독으로 쓰거나 else 뒤에 쓸 수 없습니다.",BlueprintFeature.Elif,numericBody:"사용법: 01?(조건):\n앞에서 선택된 분기가 없을 때 다음 조건을 검사합니다. 여러 개 연결할 수 있지만 첫 참 분기 하나만 실행합니다.",numericNote:"1?와 같은 들여쓰기에서 작성하세요. 01?를 단독으로 쓰거나 0? 뒤에 쓸 수 없습니다."),
        new Entry("else","조건과 반복","어느 조건도 맞지 않을 때","사용법: 0?: 또는 else:\n앞선 if/elif 조건이 모두 거짓이면 실행합니다. 조건이나 괄호를 넣지 않으며 마지막에 둡니다.","Heat = 4\n1?(Heat > 7):\n    print(\"너무 뜨겁습니다\")\n01?(Heat >= 6):\n    print(\"타격할 수 있습니다\")\n0?:\n    print(\"더 가열하세요\")","더 가열하세요 출력","else는 연결된 if가 있어야 합니다.",BlueprintFeature.Else,numericBody:"사용법: 0?:\n앞선 1?/01? 조건이 모두 거짓이면 실행합니다. 조건이나 괄호를 넣지 않으며 마지막에 둡니다.",numericNote:"0?는 연결된 1?가 있어야 합니다."),
        new Entry("while","조건과 반복","조건을 확인하며 반복","사용법: 888(조건): 또는 while 조건:\n각 회차 전에 조건을 확인합니다. 반복문 안에서 조건에 쓰는 값을 바꿔 언젠가 끝나도록 만드세요.","Count = 0\n888(Count < 3):\n    print(\"타격 준비\")\n    Count = Count + 1","타격 준비를 3번 출력","끝나지 않는 반복은 실행 한도에서 중단됩니다.",BlueprintFeature.While,numericBody:"사용법: 888(조건):\n각 회차 전에 조건을 확인합니다. 반복문 안에서 조건에 쓰는 값을 바꿔 언젠가 끝나도록 만드세요."),
        new Entry("for","조건과 반복","횟수 반복과 목록 순회","사용법: 123(이름 in 정수나목록): 또는 for 이름 in 정수나목록:\n정수 N을 넣으면 0부터 N-1까지 N번 반복합니다. 예: 123(i in 3): 다음 줄에 들여쓰기하여 print(i)를 쓰면 0, 1, 2가 출력됩니다. 0이나 음수는 반복하지 않습니다. 반복 횟수는 시작할 때 정해집니다.\n정수 리스트 또는 튜플은 시작 시점의 원소를 순서대로 순회합니다.","123(Heat in [9, 7, 5]):\n    1?(Heat <= 7):\n        print(\"7 이하 후보\")","7과 5에서 각각 출력하여 총 2번 출력","range()나 딕셔너리·집합 순회는 아직 지원하지 않습니다.",BlueprintFeature.For,numericBody:"사용법: 123(이름 in 정수나목록):\n정수 N을 넣으면 0부터 N-1까지 N번 반복합니다. 예: 123(i in 3): 다음 줄에 들여쓰기하여 print(i)를 쓰면 0, 1, 2가 출력됩니다. 0이나 음수는 반복하지 않습니다. 반복 횟수는 시작할 때 정해집니다.\n정수 리스트 또는 튜플은 시작 시점의 원소를 순서대로 순회합니다.",numericNote:"범위 생성 함수나 딕셔너리·집합 순회는 아직 지원하지 않습니다."),
        new Entry("break","조건과 반복","반복을 즉시 끝내기","사용법: !! 또는 break\n가장 가까운 반복문 하나를 종료합니다. 바깥쪽 반복문이나 함수 전체를 끝내지는 않습니다.","123(Heat in [9, 7, 5]):\n    1?(Heat <= 7):\n        print(\"첫 적합값 발견\")\n        !!","후보 7에서 한 번 출력하고 반복 종료","반복문 밖에서 사용하면 오류입니다. !Blade(완성품 판정)와 다릅니다.",BlueprintFeature.Break,numericBody:"사용법: !!\n가장 가까운 반복문 하나를 종료합니다. 바깥쪽 반복문이나 함수 전체를 끝내지는 않습니다."),
        new Entry("continue","조건과 반복","다음 회차로 건너뛰기","사용법: ~~ 또는 continue\n현재 회차의 남은 명령을 건너뛰고 가장 가까운 반복문의 다음 회차로 갑니다.","123(Heat in [9, 7, 5]):\n    1?(Heat > 7):\n        ~~\n    print(\"사용할 수 있는 후보\")","9는 건너뛰고 나머지 두 회차에서 출력","while에서는 continue 전에 카운터를 바꾸지 않으면 같은 회차 조건이 계속 반복될 수 있습니다.",BlueprintFeature.Continue,numericBody:"사용법: ~~\n현재 회차의 남은 명령을 건너뛰고 가장 가까운 반복문의 다음 회차로 갑니다.",numericNote:"888에서는 ~~ 전에 카운터를 바꾸지 않으면 같은 회차 조건이 계속 반복될 수 있습니다."),
        new Entry("def","사용자 함수","내 함수 만들기","사용법: 333 함수명(매개변수): 또는 def 함수명(매개변수):\n정의만으로는 본문이 실행되지 않습니다. 함수명(값)으로 호출합니다. 최대 8개 매개변수를 받을 수 있습니다.\n필요한 값은 인자로 전달하세요. 함수 안의 변수는 해당 호출에서만 사용합니다.","333 message(ready):\n    1?(ready):\n        << \"준비 완료\"\n    << \"대기 중\"\nprint(message(True))","message(True)가 준비 완료를 반환해 출력","함수는 도면 최상위에서 정의합니다. 직접·상호 재귀를 지원합니다. 종료 조건을 넣으세요. 동시 호출 깊이는 32단계입니다. 333: 문법은 사용하지 않습니다.",BlueprintFeature.Def,numericBody:"사용법: 333 함수명(매개변수):\n정의만으로는 본문이 실행되지 않습니다. 함수명(값)으로 호출합니다. 최대 8개 매개변수를 받을 수 있습니다.\n필요한 값은 인자로 전달하세요. 함수 안의 변수는 해당 호출에서만 사용합니다."),
        new Entry("recursion","사용자 함수","재귀 · 함수를 다시 호출하기","함수가 자기 자신을 호출하거나 다른 함수와 서로 호출할 수 있습니다. 각 호출의 매개변수·지역 변수는 독립적이며, 반환하면 이전 호출로 돌아갑니다.\n반드시 종료 조건을 넣으세요. import로 가져온 함수도 재귀를 사용할 수 있고, 재귀 속 공정도 순서대로 실행됩니다.","333 factorial(n):\n    1?(n <= 1):\n        << 1\n    << n * factorial(n - 1)\nprint(factorial(5))","120 출력","동시에 열린 함수 호출은 최대 32단계, 전체 실행은 21억 명령입니다. 한도를 넘으면 실행 오류로 중단하며 이미 성공한 공정의 비용은 유지합니다. 모듈 초기화 중 서로 가져오는 순환 import 제한은 별도입니다.",BlueprintFeature.None),
        new Entry("import","사용자 함수","import · 다른 코드창 가져오기","코드창 제목이 모듈 이름입니다. 제목을 smith처럼 문자 또는 _로 시작하는 공백 없는 이름으로 지정하세요. 한글 이름도 가능합니다.\nimport smith 후 smith.forge(1)로 호출합니다. import smith as s 후 s.forge(1)도 같습니다.\nfrom smith import forge 또는 from smith import forge as make로 함수를 직접 가져옵니다. 쉼표로 여러 이름을 지정할 수 있고 from smith import *는 _로 시작하지 않는 이름을 가져옵니다.\n가져온 창의 최상위 코드는 한 실행에서 처음 가져올 때 한 번 실행됩니다. 함수는 자신이 정의된 모듈의 변수와 함수를 읽습니다. 비용·재고·대장장이 동작은 호출한 실행에 합산됩니다.","import smith as s\nBlade = s.forge(1)\n!Blade","smith 창의 제작 함수 실행 · 철 1개 · 제작비 0G · 판매가 28G","먼저 다른 코드창의 제목을 smith로 바꾸고 아래 함수를 작성하세요.\n333 forge(material):\n    blade = 1(material)\n    2(blade)\n    3(blade)\n    4(blade, 0)\n    << blade\n\n창 제목이 중복되면 가져올 수 없습니다. 순환 import·외부 Python 패키지·상대 경로는 지원하지 않습니다. 가져온 사용자 함수 안에서도 ! 제출이 가능합니다. 가져온 창의 최상위에서 직접 제출하는 것은 허용되지 않습니다. 모듈을 수정한 내용은 다음 실행부터 적용됩니다.",BlueprintFeature.None),
        new Entry("return","사용자 함수","함수 결과 돌려주기","사용법: << 값 또는 return 값\n현재 함수를 즉시 끝내고 값을 호출한 곳으로 돌려줍니다. 함수 안의 반복문 속에서도 함수를 끝냅니다.\n값을 생략하거나 return 없이 끝나면 None입니다.","333 message(ready):\n    1?(ready):\n        << \"준비 완료\"\n    << \"대기 중\"\nprint(message(True))","준비 완료 출력","함수 밖에서 사용할 수 없습니다. <<는 !완성품 판정과 다릅니다.",BlueprintFeature.Return,numericBody:"사용법: << 값\n현재 함수를 즉시 끝내고 값을 호출한 곳으로 돌려줍니다. 함수 안의 반복문 속에서도 함수를 끝냅니다.\n값을 생략하거나 << 없이 끝나면 None입니다."),
        new Entry("heat","조회와 계산","현재 온도와 적정 온도 읽기","사용법: 100(작업물) 또는 heat(작업물)\n100(작업물)은 현재 온도를 정수로 반환합니다. 100(검날, 1)은 한 번 가열한 철·별철 검날의 적정 온도(850~1100°C)를 반환합니다. 냉각 상태는 0이며 측정은 무료입니다. 적정 온도는 검마다 고정됩니다.","Blade = 1(1)\n2(Blade)\nHeat = 100(Blade)\nTarget = 100(Blade, 1)\nprint(Heat, Target)","기본 화로로 가열했다면 현재 온도 900 반환","숫자 1 자체는 작업물이 아닙니다. 먼저 Blade = 1(1)로 만든 작업물을 넣으세요.",BlueprintFeature.Heat,numericBody:"사용법: 100(작업물)\n100(작업물)은 현재 온도를 정수로 반환합니다. 100(검날, 1)은 한 번 가열한 철·별철 검날의 적정 온도(850~1100°C)를 반환합니다. 냉각 상태는 0이며 측정은 무료입니다. 적정 온도는 검마다 고정됩니다."),
        new Entry("abs","조회와 계산","절댓값","사용법: 101(정수) 또는 abs(정수)\n음수의 부호를 없앤 크기를 반환합니다. 재료의 열을 바꾸는 기능은 아닙니다.","Distance = 101(-3) # 3","절댓값은 3 출력","정수 범위를 넘는 결과는 오류입니다.",BlueprintFeature.Abs,numericBody:"사용법: 101(정수)\n음수의 부호를 없앤 크기를 반환합니다. 재료의 열을 바꾸는 기능은 아닙니다."),
        new Entry("len","조회와 계산","원소 수 세기","사용법: 1111(컬렉션) 또는 len(컬렉션)\n리스트·튜플·집합·딕셔너리의 원소 수를 반환합니다. 빈 대상은 0입니다.","Count = 1111([9, 7, 5]) # 3","후보는 3개 출력","현재 len(\"문자열\")은 지원하지 않습니다.",BlueprintFeature.Len,numericBody:"사용법: 1111(컬렉션)\n리스트·튜플·집합·딕셔너리의 원소 수를 반환합니다. 빈 대상은 0입니다.",numericNote:"현재 1111(\"문자열\")은 지원하지 않습니다."),
        new Entry("min","조회와 계산","최솟값","사용법: 000(목록) 또는 min(목록)\n정수 리스트 또는 튜플에서 가장 작은 값을 반환합니다.","Target = 000([9, 7, 5]) # 5","Target은 5, 값 찾기 메시지 출력","빈 목록, 딕셔너리, 집합은 인자로 사용할 수 없습니다.",BlueprintFeature.Min,numericBody:"사용법: 000(목록)\n정수 리스트 또는 튜플에서 가장 작은 값을 반환합니다."),
        new Entry("max","조회와 계산","최댓값","사용법: 999(목록) 또는 max(목록)\n정수 리스트 또는 튜플에서 가장 큰 값을 반환합니다.","Target = 999([9, 7, 5]) # 9","Target은 9, 값 찾기 메시지 출력","빈 목록, 딕셔너리, 집합은 인자로 사용할 수 없습니다.",BlueprintFeature.Max,numericBody:"사용법: 999(목록)\n정수 리스트 또는 튜플에서 가장 큰 값을 반환합니다."),
        new Entry("random","조회와 계산","무작위 정수","사용법: 66(최솟값, 최댓값) 또는 random(최솟값, 최댓값)\n두 경계를 모두 포함한 정수 하나를 돌려줍니다. 66(1, 7)은 1과 7도 나올 수 있습니다.","Roll = 66(1, 7) # 1~7 중 하나","범위 안의 정수 선택 후 메시지 출력","인자는 반드시 두 개이고 최솟값 ≤ 최댓값이어야 합니다. 한 줄 실행과 전체 실행은 같은 시작 상태에서 같은 난수 순서를 사용합니다. 멈췄다가 이어 실행해도 난수를 다시 뽑지 않습니다.",BlueprintFeature.Random,numericBody:"사용법: 66(최솟값, 최댓값)\n두 경계를 모두 포함한 정수 하나를 돌려줍니다. 66(1, 7)은 1과 7도 나올 수 있습니다."),
        new Entry("set","자료 묶음","빈 집합 만들기","사용법: 1010() 또는 set()\n중복 원소가 없는 빈 정수 집합을 돌려줍니다. 원소를 지정할 때는 {0, 1}처럼 작성합니다.","Empty = 1010()","빈 집합입니다 출력","set([1, 2])는 지원하지 않습니다. {}는 빈 집합이 아닌 빈 딕셔너리입니다.",BlueprintFeature.Set,numericBody:"사용법: 1010()\n중복 원소가 없는 빈 정수 집합을 돌려줍니다. 원소를 지정할 때는 {0, 1}처럼 작성합니다.",numericNote:"1010([1, 2])는 지원하지 않습니다. {}는 빈 집합이 아닌 빈 딕셔너리입니다."),
        new Entry("print","출력","여러 값과 변수 출력","사용법: print(값, ...)\n문자열뿐 아니라 정수, True/False, None, 변수, 계산 결과, 컬렉션과 작업물을 출력합니다.\n여러 인자는 쉼표로 나누어 전달하며, 출력에서는 공백으로 구분됩니다. print()는 빈 줄을 출력합니다.\n리스트는 [1, 2], 튜플은 (1, 2), 집합은 {1, 2}, 딕셔너리는 {1: 2} 형태로 표시됩니다. print(Blade)는 작업물의 열·성형 여부·특성을 보여줍니다.\n비용은 0G이며 None을 반환합니다. 출력 전용 코드는 ! 없이 실행할 수 있습니다. 실제로 실행된 메시지만 순서대로 표시합니다.","value = 7\nprint(\"안녕하세요\")\nprint(\"현재 값:\", value, \"계산:\", value + 3)\nprint(True, False, None)\nprint([1, 2, 3], (4, 5), {6: 7})\nprint()","안녕하세요\n현재 값: 7 계산: 10\nTrue False None\n[1, 2, 3] (4, 5) {6: 7}\n(마지막에 빈 줄 출력)","지원하는 도면 언어 값에 한해 출력합니다. 컬렉션 원소는 정수만 지원합니다. sep/end 키워드 인자, f문자열은 아직 지원하지 않습니다. 실행당 최대 256회/65536자입니다.",BlueprintFeature.Print),
        new Entry("list","자료 묶음","리스트 · 순서 있는 목록","[9, 7, 5]처럼 정수를 순서대로 담습니다. 인덱스는 0부터 시작하며 변수[인덱스]로 읽거나 바꿀 수 있습니다.\n목록을 다른 변수에 대입하면 복사됩니다.","Values = [9, 7, 5]\nValues[0] = 7\n1?(Values[0] == 7):\n    print(\"첫 후보를 바꿨습니다\")","첫 후보를 바꿨습니다 출력","음수/범위 밖 인덱스는 오류입니다. 301(목록,값)으로 추가하고 302(목록)으로 마지막 원소를 꺼냅니다.",BlueprintFeature.None,numericNote:"음수/범위 밖 인덱스는 오류입니다. 301(목록,값)으로 추가하고 302(목록)으로 마지막 원소를 꺼냅니다."),
        new Entry("dict","자료 묶음","딕셔너리 · 번호별 수량","{1: 3}은 번호 1에 수량 3을 연결합니다. 정수 키와 정수 값만 담을 수 있습니다.\n없는 키에 대입하면 새 항목을 만들고, 같은 키에 다시 대입하면 값을 바꿉니다.","Stock = {1: 3}\nStock[1] = Stock[1] - 1\n1?(Stock[1] == 2):\n    print(\"기록한 수량은 2\")","기록한 수량은 2 출력","없는 키를 읽으면 그 줄에서 오류입니다. 이 목록은 플레이어의 계산용 기록이며 실제 철 재고를 바꾸지 않습니다.",BlueprintFeature.None),
        new Entry("tuple","자료 묶음","튜플 · 고정된 묶음","(6, 7)처럼 변경하지 않을 정수 묶음을 만듭니다. 인덱스로 읽고, for로 순회하고, min/max/len에 넣을 수 있습니다.","Bounds = (6, 7)\n1?(000(Bounds) == 6):\n    print(\"최저 기준은 6\")","최저 기준은 6 출력","Bounds[0] = 5처럼 바꿀 수 없습니다. 원소 하나짜리는 (6,)이고 빈 튜플은 ()입니다.",BlueprintFeature.None,numericBody:"(6, 7)처럼 변경하지 않을 정수 묶음을 만듭니다. 인덱스로 읽고, 123로 순회하고, 000/999/1111에 넣을 수 있습니다."),
        new Entry("membership","자료 묶음","집합과 포함 여부 in","{0, 0, 1}은 중복 0을 하나로 합쳐 {0, 1}이 됩니다. 값 in 대상은 포함 여부를 True/False로 반환합니다.\n리스트·튜플·집합에서는 원소, 딕셔너리에서는 키를 확인합니다.","Allowed = {0, 0, 1}\n1?(0 in Allowed):\n    print(\"공기 냉각 허용\")","공기 냉각 허용 출력","현재 컬렉션에는 정수만 넣을 수 있으며 한 컬렉션은 최대 1024개입니다.",BlueprintFeature.None),
        new Entry("operators","기본 문법","계산 · 비교 · 논리","계산: + 더하기, - 빼기/음수, * 곱하기, // 몫, % 나머지\n비교: == 같음, != 다름, < 작음, <= 이하, > 큼, >= 이상\n논리: and 둘 다 참, or 하나 이상 참, not 반대로\nTrue는 참, False는 거짓, None은 값 없음입니다.","Heat = 7\nReady = Heat >= 6 and Heat <= 7\n1?(Ready):\n    print(\"타격 가능한 열\")","타격 가능한 열 출력","6 <= Heat <= 7 대신 and로 연결하세요. / 나누기·소수는 없습니다. 0으로 나누거나 정수 범위를 넘으면 오류입니다.",BlueprintFeature.None),
        new Entry("stages","반복","반복으로 공정 순서 만들기","a를 1부터 늘리며 한 회차에 한 공정을 선택합니다. 첫 회차에서 만든 res를 다음 회차와 반복문 밖에서도 사용합니다.","a = 1\n888(True):\n    1? a == 1:\n        res = 1(a)\n    01? a == 2:\n        2(res)\n    01? a == 3:\n        3(res)\n    01? a == 4:\n        4(res, 0)\n    01? a == 5:\n        !!\n    a = a + 1\n!res","철 1개 · 제작비 0G · 완성품 생성","a가 5가 되면 !!로 반복을 끝내고, 바깥의 !res로 완성품을 판정합니다.",BlueprintFeature.None),
        new Entry("choose","완성 예제","첫 적합 후보 찾기","사용자 함수가 [9, 7, 5]에서 제한 7 이하인 첫 후보를 찾습니다. 후보가 있으면 기본 화로로 검을 만듭니다. 후보 숫자는 온도가 아닙니다.","333 choose(values, limit):\n    selected = None\n    123(candidate in values):\n        1?(candidate <= limit):\n            selected = candidate\n            !!\n    << selected\nTarget = choose([9, 7, 5], 7)\n1?(Target != None):\n    Blade = 1(1)\n    2(Blade)\n    3(Blade)\n    4(Blade, 0)\n    !Blade\n0?:\n    print(\"맞는 후보가 없습니다\")","후보 7 선택 · 가열 1회 · 제작비 0G","목록을 [9, 8]로 바꾸면 공정과 비용 없이 안내 메시지만 출력합니다.",BlueprintFeature.None),
        new Entry("errors","문제가 생겼을 때","오류와 비용 확인","▷로 시작하면 앞부분부터 실행하고 문법·함수 이름·인자 수 오류는 해당 줄에 도달했을 때 표시합니다. 새로 ▶로 시작할 때는 전체 문법 검사를 먼저 합니다.\n변수의 값과 현재 타입, 공정 상태는 실제 실행 시점에 확인합니다. 함수·분기 안의 오류도 실행 경로가 도달했을 때 중단합니다. 괄호·따옴표·들여쓰기 오류는 안전하게 해석 가능한 앞부분까지만 진행합니다. 오류 줄 이후는 실행하지 않습니다.\n실제 제작에서 이미 소비한 재료는 돌아오지 않습니다. ▷로 한 줄씩 확인할 수 있지만 실제 재료가 소비됩니다. 아직 실행하지 않은 줄의 공정과 출력은 발생하지 않습니다.\n실행 명령 21억 회, 함수 호출 깊이 32입니다. 재귀도 같은 한도를 공유합니다.","Material = 1\nBlade = 1(Material)\n2(Blade)\n3(Blade)\n4(Blade, 0)\n!Blade","정상 기본 도면: 제작비 0G · 판매가 28G","가열을 한 번 더 해도 같은 상태의 검날 판매가는 28G입니다. 추가 가열에도 골드는 소비되지 않습니다.",BlueprintFeature.None)
    }.Concat(ForgeExpansion.Definitions.Where(d=>d.Alias.Id!=BlueprintFeature.Attach).Select(d=>d.Alias.Id==BlueprintFeature.Rune||d.Alias.Id==BlueprintFeature.RuneList||d.Alias.Id==BlueprintFeature.RuneFamily||d.Alias.Id==BlueprintFeature.RuneGrade||d.Alias.Id==BlueprintFeature.Slots?RuneReference(d):d.Alias.Id==BlueprintFeature.Charge||d.Alias.Id==BlueprintFeature.Inspect||d.Alias.Id==BlueprintFeature.Strength?MagicReference(d):d.Alias.Id==BlueprintFeature.Polish?PolishEntry():d.Alias.Id==BlueprintFeature.Fuel?FuelEntry():d.Alias.Id==BlueprintFeature.Wrap||d.Alias.Id==BlueprintFeature.Unwrap||d.Alias.Id==BlueprintFeature.SealCount?SealEntry(d.Alias.Id):new Entry("extension-"+d.Alias.Symbol,(d.Alias.Id==BlueprintFeature.Lucky||d.Alias.Id==BlueprintFeature.LuckyCode)?"조회와 계산":"확장 제작",d.Alias.Symbol+"()"+(d.Alias.Id==BlueprintFeature.Append?" · 목록 끝에 값 추가":d.Alias.Id==BlueprintFeature.Pop?" · 목록 마지막 값 꺼내기":d.Alias.Id==BlueprintFeature.SetAdd?" · 집합에 값 추가":d.Alias.Id==BlueprintFeature.Speed?" · 제작 속도 설정":d.Alias.Id==BlueprintFeature.AutoSell?" · 자동판매 설정":d.Alias.Id==BlueprintFeature.Refine?" · 용뼈 정제":d.Alias.Id==BlueprintFeature.Curse?" · 저주 부여":d.Alias.Id==BlueprintFeature.Plate?" · 은도금":d.Alias.Id==BlueprintFeature.Magic?" · 마력 단조 활성화":d.Alias.Id==BlueprintFeature.Recover?" · 재료 회수":d.Alias.Id==BlueprintFeature.Wait?" · 지정 시간 대기":d.Alias.Id==BlueprintFeature.Lucky?" · 오늘의 행운 적용":d.Alias.Id==BlueprintFeature.LuckyCode?" · 오늘 행운 코드 조회":d.Alias.Id==BlueprintFeature.Resonate?" · 공명 검사":d.Alias.Id==BlueprintFeature.Protect?" · 파괴 보호":d.Alias.Id==BlueprintFeature.Rune?" · 룬 각인":d.Alias.Id==BlueprintFeature.RuneList?" · 룬 후보 목록 조회":d.Alias.Id==BlueprintFeature.RuneFamily?" · 룬 계열 조회":d.Alias.Id==BlueprintFeature.RuneGrade?" · 룬 등급 조회":d.Alias.Id==BlueprintFeature.Slots?" · 남은 룬 슬롯 조회":""),d.Alias.Description,d.Example,"함수 설명에 따라 공정·반환값이 적용됩니다.","함수 호출의 골드 비용과 연구비·재료 구매비는 별개입니다.",d.Alias.Id))).Concat(new[]{
        new Entry("is-day","시간 조회","12() · 낮인지 확인","정오의 12에서 연상합니다. 06:00 이상 18:00 미만이면 정수 1, 나머지 시간에는 0입니다. 호출 순간의 게임 시각을 읽으며 자원은 소비하지 않습니다.","Daylight = 12()\nprint(Daylight)\n1? Daylight == 1:\n    print(\"낮입니다\")","오전 8시 예: 1과 낮입니다 출력","시간 조회 묶음(12 + 24)을 "+ForgeTechnology.Find("function-IsDay").Price+"G로 함께 해금합니다. 반환값은 bool이 아닌 정수이므로 조건에는 12() == 1처럼 비교하세요.",BlueprintFeature.IsDay),
        new Entry("night-time","시간 조회","24() · 밤인지 확인","자정의 24에서 연상합니다. 18:00 이상 또는 06:00 미만이면 정수 1, 낮이면 0입니다. 24(60) 시각 조회도 함께 해금됩니다.","Night = 24()\nprint(Night)\n1? Night == 1:\n    print(\"밤입니다\")","오전 8시 예: 0 출력","시간 조회 묶음(12 + 24)을 "+ForgeTechnology.Find("function-IsDay").Price+"G로 함께 해금합니다. 조건에는 24() == 1처럼 비교하세요. 호출 비용은 0G입니다.",BlueprintFeature.NightTime),
        new Entry("clock-minutes","시간 조회","24(60) · 현재 시각 조회","하루 24시간과 한 시간 60분을 연결합니다. 자정부터 지난 분을 0~1439의 정수로 반환하며 초는 버립니다. 24:00에는 0으로 돌아갑니다. 한 줄 실행에서도 각 호출 시점의 시각을 읽습니다.","Minutes = 24(60)\nHour = Minutes // 60\nMinute = Minutes % 60\nprint(Hour, Minute)","오전 8시 예: 8 0 출력","24() 해금에 포함됩니다. 인자는 정수 60만 허용합니다. 현실 시간이 아닌 게임 속 시각이며 기본 하루는 현실 10분입니다. 호출 비용과 재료 소비는 없습니다.",BlueprintFeature.None),
        new Entry("masterwork-example","완성 예제","명장의 마지막 의뢰 · 완성 도면","검 자체 판매가 7,000G 이상이면 성공합니다. 대장장이 판매 배율은 제외하며, 재료·가공·저주 효과는 포함합니다. 의뢰와 예제의 가공 기능을 먼저 해금하세요.","p = 1(7)\n2(p)\n3(p)\n4(p, 3)\n6(p)\n7(p)\nb = 1(9)\n10(b, p, 100, 6)\n5(p, b)\n9(p, 1)\n9(p, 1)\n9(p, 1)\n123(r in [7, 8, 9]):\n    211(p, r)\n123(i in 6):\n    201(p, 3)\n123(i in 6):\n    202(p, 3)\nc = 1(6)\n123(i in 9):\n    8((i + 1) * 100)\n    2(c)\n    1?(501(c) == 0):\n        !!\n4(c, 0)\n5(p, c)\n667(p)\n666(p)\n!p","대장장이 판매 배율 제외 7,000G 이상 검 제출","재료: 별철 2개, 은 1개, 용뼈 2개, 서리수 1개, 물 2개, 나무 6개, 마력 수정 4개, 석탄 최대 9개. 봉인 해제·공명·저주 보호와 저주가 필요합니다. 의뢰 수락 후 완성품을 제출하세요.",BlueprintFeature.None),
    }).Concat(ForgeSmithLanguage.Aliases.Select(a=>new Entry("extension-smith-"+a.Symbol,"대장장이와 다이아몬드",a.Symbol+"() · "+ForgeSmithLanguage.GuideTitle(a.Id),a.Id==BlueprintFeature.SmithRun?ForgeSmithLanguage.RunGuideBody:a.Description,ForgeSmithLanguage.Example(a.Id),a.Id==BlueprintFeature.SmithRun?"고용한 대장장이 1번이 독립 실행하고 반환한 검을 제출합니다.":"공방의 해당 대장장이 상태를 조회하거나 변경합니다.",a.Id==BlueprintFeature.SmithRun?ForgeSmithLanguage.RunGuideNote:ForgeSmithLanguage.IsGiantRune(a.Id)?"룬 각인·거대한 룬 연구를 구매하면 설치와 시간 조회가 함께 열립니다. 룬 번호는 1~9이며 좌표는 공방 격자 기준입니다. 조회 비용은 없습니다. 소수는 0.25처럼 적고 변수·계산식으로 전달할 수 있습니다.":"대장장이 번호는 0부터 시작합니다. 첫 위치는 (0,0)입니다. 대장장이 함수는 코드창에서 연파랑으로 표시합니다. 조회 연구와 고용은 대장장이 테크 트리에서 다이아로 구매합니다. 예제 실행 전 필요한 고용·연구·재료를 준비하세요.",a.Id))).Concat(new[]{MatchGuide(),new Entry("increment","기본 문법","++ · -- · 전위/후위 증감","별도 연구 없이 정수 값을 1씩 늘리거나 줄입니다. Python 표준 문법이 아닌 이 게임의 확장 문법입니다.\n\ni++ / i--: 값을 변경하고 변경 전 값을 반환합니다.\n++i / --i: 값을 먼저 변경하고 변경 후 값을 반환합니다.\n단독 줄, 계산식, 함수 인자, 조건식에서 사용할 수 있습니다. 여러 항은 왼쪽부터 평가하며 and/or로 생략된 항은 증감하지 않습니다.\n\n값들[i]++, ++값들[i]처럼 이름으로 저장한 리스트·딕셔너리의 기존 정수 원소도 지원합니다. 인덱스 식은 한 번만 평가합니다. 튜플·슬라이스·상수·함수 반환값에는 사용할 수 없습니다.","i = 3\na = i++\nb = ++i\nc = i--\nd = --i\nprint(a, b, c, d, i)","3 5 5 3 3 출력","값을 먼저 대입해야 합니다. 불리언·문자열은 지원하지 않습니다. 없는 인덱스/키 또는 정수 범위 초과 시 대상 값은 변경하지 않고 오류를 표시합니다. 함수 안의 변수 증감은 기존 지역 대입 규칙을 따릅니다. --i는 감소이며, 부호 반전 두 번은 -(-i)로 작성하세요.",BlueprintFeature.None)}).Concat(BlueprintAliases.All.Where(a=>a.Id!=BlueprintFeature.StarlightEngrave&&ForgeStarlight.IsFeature(a.Id)||ForgeCoolingGraph.IsFeature(a.Id)||ForgeDragonBone.IsFeature(a.Id)).OrderBy(a=>int.Parse(a.Symbol)).Select(MaterialFunction)).Concat(new[]{new Entry("master-commission","대장장이와 다이아몬드","명장의 마지막 의뢰",
        "【성공 조건】\n테크 트리에서 ‘명장의 마지막 의뢰’를 수락한 뒤, 검 자체 판매가 7,000G 이상인 완성품을 !로 제출하세요.\n\n【가격에 포함되는 효과】\n재료·정제·가공·룬·저주 효과는 포함합니다. 불타는 대장장이를 포함한 대장장이 판매 배율을 제외합니다. 재료비를 뺀 순이익이 아니라 검 자체의 판매가를 기준으로 합니다.\n\n【판정 예시】\n검 자체 판매가 6,000G에 대장장이 2배가 붙어 12,000G가 되어도 실패합니다. 검 자체 판매가가 7,000G 이상이면 대장장이 배율과 관계없이 성공합니다.\n\n특정 재료나 룬 조합을 요구하지 않습니다. 실제 판매 대금에는 대장장이 배율이 그대로 적용됩니다.","","","",BlueprintFeature.None),new Entry("starlight-engrave","금속 가공","74() · 별빛 각인","별철 공급을 해금하면 사용할 수 있습니다. 별철 칼날 작업물을 인자로 받으며 반환값은 없습니다. 게임 시간 01:00 이상~05:00 미만에 사용하면 최종 판매 보너스 +100G를 얻습니다. 다른 시간에는 보너스를 새로 얻지 못하며, 해당 시간에 다시 사용할 수 있습니다.\n별빛 정제 +250G와 별개이며, 반복 사용해도 각인 보너스는 한 번만 적용됩니다. 이후 시간이 지나도 획득한 각인은 유지됩니다.","StarIron = 1(7)\n74(StarIron)","","별철이 아닌 대상, 잘못된 인자, 파괴·회수된 작업물은 실행 오류입니다. 작업 시간은 기본 0.8초입니다.",BlueprintFeature.StarlightEngrave)}).ToArray());
